// WF04 F15 — validate the create request and build the provisioning key.
// Payload contract (schema_version 1.1.0):
// { brandName, clientEmail, company_id, planner_kind, templateSheetId, timezone? }
// provisioning_key = company_id + '::' + planner_kind — unique per company and
// planner kind (run/contracts/sheet_registry.json rule). The caller persists the
// operation in its own ledger BEFORE this call and reconciles AFTER; this
// webhook stays stateless-safe via the Drive readback that follows.
const body = $input.first().json.body || {};
const required = ['brandName', 'clientEmail', 'company_id', 'planner_kind', 'templateSheetId'];
for (const field of required) {
  if (body[field] === undefined || body[field] === null || body[field] === '') {
    throw new Error('missing required field: ' + field);
  }
}
const provisioningKey = [body.company_id, body.planner_kind].join('::');
return [{ json: {
  brandName: body.brandName,
  clientEmail: body.clientEmail,
  provisioningKey: provisioningKey,
  readbackQuery: "appProperties has { key='skill35_provisioning_key' and value='" + provisioningKey + "' } and trashed = false",
  templateSheetId: body.templateSheetId,
  body: body
} }];

// F14 — classify the template verification result BEFORE provisioning.
// Same credential class (googleDriveOAuth2Api) the copy uses, so the status is
// authoritative for the copy path:
//   404 => 'template_not_found'    — the templateSheetId is wrong or deleted
//          (identity repair: correct the registered template ID; NEVER make a
//          replacement template or an ad-hoc sheet as a side effect).
//   403 => 'template_access_denied' — the operator credential lost access to
//          the template (access repair: re-grant access to the EXISTING file).
//   other => 'transient' — bounded retries (3x/2s) already applied; surfaced so
//          the caller retries provisioning without losing the pending marker.
const src = $('Validate + Build Provisioning Key').first().json;
const err = $input.first().json;
const status = err.status || err.statusCode || (err.response && (err.response.status || err.response.statusCode));
let repair_state = 'transient';
let repair_action = 'Transient Google Drive error after 3 bounded retries — provisioning stays pending; retry the create with the SAME provisioning key (the readback dedupes).';
if (status === 404) {
  repair_state = 'template_not_found';
  repair_action = 'The template sheet ID ' + src.templateSheetId + ' does not exist or was deleted. Identity repair: correct the registered templateSheetId — do NOT provision a replacement sheet from another source silently; the pending marker reconciles once the ID is verified.';
} else if (status === 403) {
  repair_state = 'template_access_denied';
  repair_action = 'The operator Drive credential is denied access to the template ' + src.templateSheetId + '. Access repair: re-grant the operator credential access to the EXISTING template, then retry provisioning with the SAME provisioning key.';
}
return [{ json: {
  status: 'error',
  repair_required: true,
  repair_state: repair_state,
  repair_action: repair_action,
  provisioning_key: src.provisioningKey
} }];

// F15 — Drive readback. If a Drive file already carries this provisioning key
// in its appProperties, the sheet was created in a previous run (crash after
// Google succeeded, receipt lost). Return the EXISTING artifact instead of
// copying again: replay must return the existing sheet, never a duplicate.
const files = ($input.first().json.files || []);
const src = $('Validate + Build Provisioning Key').first().json;
const existing = files.length > 0 ? files[0] : null;
return [{ json: {
  existing: existing !== null,
  existingFile: existing,
  provisioningKey: src.provisioningKey,
  brandName: src.brandName,
  clientEmail: src.clientEmail,
  templateSheetId: src.templateSheetId,
  body: src.body
} }];

// F25 — build the readability/formatting provisioning requests for the NEW
// sheet from the sheet-template.schema.json contract:
//   - TEXT_EQ conditional format rules for every status (color + written
//     label — NUMBER_EQ against text is the defect this replaces and is never
//     emitted),
//   - setDataValidation dropdowns over the same status list,
//   - frozen header rows (Posts also freezes its first two columns),
//   - wrapped copy (repeatCell wrapStrategy WRAP),
//   - protected formula ranges (Images preview column P),
//   - the compact This Week view tab with its ~8 client-facing columns.
// All requests run in ONE spreadsheet.batchUpdate after the share step.
const sheets = ($input.first().json.sheets || []);
const numeric = {};
for (const s of sheets) {
  if (s.properties) numeric[s.properties.title] = s.properties.sheetId;
}
const STATUSES = [
  { label: 'Complete', color: { red: 0.718, green: 0.882, blue: 0.804 } },
  { label: 'Failed', color: { red: 0.957, green: 0.780, blue: 0.765 } },
  { label: 'QC Review', color: { red: 0.988, green: 0.910, blue: 0.698 } },
  { label: 'Scheduled', color: { red: 0.827, green: 0.890, blue: 0.992 } },
  { label: 'Published', color: { red: 0.788, green: 0.855, blue: 0.973 } },
  { label: 'Needs Attention', color: { red: 0.965, green: 0.678, blue: 0.663 } }
];
const requests = [];
const statusTabs = [];
if (numeric['Weekly Overview'] !== undefined) statusTabs.push(numeric['Weekly Overview']);
if (numeric['Posts'] !== undefined) statusTabs.push(numeric['Posts']);
for (const tabId of statusTabs) {
  for (const st of STATUSES) {
    requests.push({ addConditionalFormatRule: {
      rule: {
        ranges: [{ sheetId: tabId, startRowIndex: 1, startColumnIndex: 0, endColumnIndex: 21 }],
        booleanRule: {
          condition: { type: 'TEXT_EQ', values: [{ userEnteredValue: st.label }] },
          format: { backgroundColor: st.color }
        }
      },
      index: 0
    } });
  }
  requests.push({ setDataValidation: {
    range: { sheetId: tabId, startRowIndex: 1, startColumnIndex: 0, endColumnIndex: 21 },
    rule: {
      condition: { type: 'ONE_OF_LIST', values: STATUSES.map(s => ({ userEnteredValue: s.label })) },
      showCustomUi: true,
      strict: true
    }
  } });
  requests.push({ repeatCell: {
    range: { sheetId: tabId, startRowIndex: 1, startColumnIndex: 0, endColumnIndex: 21 },
    cell: { userEnteredFormat: { wrapStrategy: 'WRAP', verticalAlignment: 'TOP' } }
  } });
  requests.push({ updateSheetProperties: {
    properties: { sheetId: tabId, gridProperties: { frozenRowCount: 1 } },
    fields: 'gridProperties.frozenRowCount'
  } });
}
if (numeric['Posts'] !== undefined) {
  requests.push({ updateSheetProperties: {
    properties: { sheetId: numeric['Posts'], gridProperties: { frozenColumnCount: 2 } },
    fields: 'gridProperties.frozenColumnCount'
  } });
}
if (numeric['Images'] !== undefined) {
  // F25 — protect the trusted IMAGE formula column (P) from client edits.
  requests.push({ addProtectedRange: {
    protectedRange: {
      range: { sheetId: numeric['Images'], startColumnIndex: 15, endColumnIndex: 16 },
      description: 'Trusted =IMAGE formula column (F24/F25) — protected',
      warningOnly: false
    }
  } });
}
// This Week view — created only when the copy did not already carry it.
const addRequests = [];
if (numeric['This Week'] === undefined) {
  addRequests.push({ addSheet: { properties: { title: 'This Week', gridProperties: { frozenRowCount: 1, columnCount: 8, rowCount: 40 }, rightToLeft: false } } });
}
return [{ json: {
  newSheetRequests: addRequests,
  formatRequests: requests,
  statuses: STATUSES.map(s => s.label)
} }];

// F25 — resolve the freshly created 'This Week' tab (if any) and size its
// eight client-facing columns, then hand the identity fields to the response.
const created = $input.first().json;
const added = ((created || {}).replies || []).filter(r => r.addSheet).map(r => r.addSheet.properties);
const thisWeek = added.find(p => p.title === 'This Week') || null;
const requests = [];
if (thisWeek) {
  const widths = [110, 170, 220, 130, 130, 130, 130, 150];
  widths.forEach((px, i) => requests.push({ updateDimensionProperties: {
    range: { sheetId: thisWeek.sheetId, dimension: 'COLUMNS', startIndex: i, endIndex: i + 1 },
    properties: { pixelSize: px }
  } }));
  // Header labels (RAW): week, client, next action, counts, attention + links row.
  const header = ['Week', 'Client', 'Next Action', 'Drafting', 'QC', 'Scheduled', 'Published', 'Needs Attention'];
  requests.push({ updateCells: {
    rows: [{ values: header.map(v => ({ userEnteredValue: { stringValue: v } })) }],
    fields: 'userEnteredValue',
    start: { sheetId: thisWeek.sheetId, rowIndex: 0, columnIndex: 0 }
  } });
}
return [{ json: { identityStamps: requests, thisWeekCreated: thisWeek !== null } }];
